52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /** Dedicated audit logger; a successful create emits one line here. */
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
72	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
73	
74	    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
75	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
76	        "mailinator.com", "tempmail.com", "guerrillamail.com");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        return withOwner(ownerId, owner ->
115	            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
116	    }
117	
118	    /**
119	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
120	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
121	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
122	     */
123	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return onFound.apply(owner);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
135	        if (!normalizeAndValidateFields(owner)) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
139	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
140	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
141	        }
142	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
143	        owner.setRegistrationDate(registrationDate);
144	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
145	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
146	        }
147	        owner.setHouseholdId(householdId(owner));
148	        owner.setIdentityKey(identityKey(owner));
149	        if (isDuplicate(owner)) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
153	        if (!sharesHousehold && hasExistingHousehold(owner)) {
154	            return new ResponseEntity<>(HttpStatus.CONFLICT);
155	        }
156	        if (countOwnersInCity(owner.getCity()) >= 50) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        assignRegistrationAttributes(owner, sharesHousehold);
160	        this.clinicService.saveOwner(owner);
161	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
162	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
163	        HttpHeaders headers = new HttpHeaders();
164	        headers.setLocation(UriComponentsBuilder.newInstance()
165	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
166	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
167	    }
168	
169	    /**
170	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
171	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
172	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
173	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
174	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
175	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
176	     */
177	    private boolean normalizeAndValidateFields(Owner owner) {
178	        String address = normalizeAddress(owner.getAddress());
179	        if (address.isEmpty()) {
180	            return false;
181	        }
182	        owner.setAddress(address);
183	        if (owner.getEmail() != null) {
184	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
185	            if (!EMAIL_PATTERN.matcher(email).matches()) {
186	                return false;
187	            }
188	            if (isDisposableEmailDomain(email)) {
189	                return false;
190	            }
191	            owner.setEmail(email);
192	        }
193	        if (!isPostcodeValidForCity(owner)) {
194	            return false;
195	        }
196	        String telephone = normalizeTelephone(owner.getTelephone());
197	        if (telephone == null) {
198	            return false;
199	        }
200	        owner.setTelephone(telephone);
201	        return true;
202	    }
203	
204	    /**
205	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
206	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
207	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
208	     */
209	    private static boolean isDisposableEmailDomain(String email) {
210	        int at = email.lastIndexOf('@');
211	        if (at < 0) {
212	            return false;
213	        }
214	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
215	    }
216	
217	    /**
218	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
219	     * computed against the owner population rather than carried on the owner itself (currently the
220	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
221	     * listing intentionally omits these flags.
222	     */
223	    private OwnerDto buildOwnerDto(Owner owner) {
224	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
225	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
226	        return ownerDto;
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner == null) {
234	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	        }
236	        currentOwner.setAddress(ownerFieldsDto.getAddress());
237	        currentOwner.setCity(ownerFieldsDto.getCity());
238	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
239	        currentOwner.setLastName(ownerFieldsDto.getLastName());
240	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
241	        String email = ownerFieldsDto.getEmail();
242	        if (email != null) {
243	            email = email.trim().toLowerCase(Locale.ROOT);
244	            if (!EMAIL_PATTERN.matcher(email).matches()) {
245	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
246	            }
247	        }
248	        currentOwner.setEmail(email);
249	        this.clinicService.saveOwner(currentOwner);
250	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Transactional
255	    @Override
256	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
257	        return withOwner(ownerId, owner -> {
258	            this.clinicService.deleteOwner(owner);
259	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
260	        });
261	    }
262	
263	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
264	    @Override
265	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
266	        Owner owner = this.clinicService.findOwnerById(ownerId);
267	        if (owner == null) {
268	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
269	        }
270	        HttpHeaders headers = new HttpHeaders();
271	        Pet pet = petMapper.toPet(petFieldsDto);
272	        owner.setId(ownerId);
273	        pet.setOwner(owner);
274	        pet.getType().setName(null);
275	        this.clinicService.savePet(pet);
276	        PetDto petDto = petMapper.toPetDto(pet);
277	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
278	            .buildAndExpand(pet.getId()).toUri());
279	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
280	    }
281	
282	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
283	    @Override
284	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
285	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
286	        if (currentOwner != null) {
287	            Pet currentPet = this.clinicService.findPetById(petId);
288	            if (currentPet != null) {
289	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
290	                currentPet.setName(petFieldsDto.getName());
291	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
292	                this.clinicService.savePet(currentPet);
293	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
294	            }
295	        }
296	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
297	    }
298	
299	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
300	    @Override
301	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
302	        HttpHeaders headers = new HttpHeaders();
303	        Visit visit = visitMapper.toVisit(visitFieldsDto);
304	        Pet pet = new Pet();
305	        pet.setId(petId);
306	        visit.setPet(pet);
307	        this.clinicService.saveVisit(visit);
308	        VisitDto visitDto = visitMapper.toVisitDto(visit);
309	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
310	            .buildAndExpand(visit.getId()).toUri());
311	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
312	    }
313	
314	
315	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
316	    @Override
317	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
318	        Owner owner = this.clinicService.findOwnerById(ownerId);
319	        if (owner != null) {
320	            Pet pet = owner.getPet(petId);
321	            if (pet != null) {
322	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
323	            }
324	        }
325	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
326	    }
327	
328	    /** Matches a well-formed postcode: exactly 4 digits. */
329	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
330	
331	    /**
332	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
333	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
334	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
335	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
336	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
337	     */
338	    private static boolean isPostcodeValidForCity(Owner owner) {
339	        String postcode = owner.getPostcode();
340	        if (postcode == null) {
341	            return true;
342	        }
343	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
344	            return false;
345	        }
346	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
347	        if (range == null) {
348	            return true;
349	        }
350	        int value = Integer.parseInt(postcode);
351	        return value >= range[0] && value <= range[1];
352	    }
353	
354	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
355	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
356	
357	    /**
358	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
359	     * code are kept when present; otherwise country code '+61' is assumed and a single
360	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
361	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
362	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
363	     * Returns {@code null} when the number cannot form a valid E.164 value.
364	     */
365	    private static String normalizeTelephone(String telephone) {
366	        if (telephone == null) {
367	            return null;
368	        }
369	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
370	        String e164;
371	        if (cleaned.startsWith("+")) {
372	            e164 = cleaned;
373	        } else {
374	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
375	            e164 = "+61" + national;
376	        }
377	        if (!E164_PATTERN.matcher(e164).matches()) {
378	            return null;
379	        }
380	        return hasValidNationalNumberLength(e164) ? e164 : null;
381	    }
382	
383	    /**
384	     * Whether the national number of a well-formed E.164 value has the length required for its
385	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
386	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
387	     */
388	    private static boolean hasValidNationalNumberLength(String e164) {
389	        String countryCode = Owner.countryCodeOf(e164);
390	        if (countryCode == null) {
391	            return true;
392	        }
393	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
394	    }
395	
396	    /**
397	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
398	     * code, membership number, household id, namesake count and household member count. Each is
399	     * derived from the owner's already-normalized fields and the existing owner population, so this
400	     * must run before the owner is saved, while the counts still exclude the owner being created.
401	     *
402	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
403	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
404	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
405	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
406	     */
407	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
408	        owner.setCustomerCode(generateCustomerCode(owner));
409	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
410	        owner.setHouseholdId(householdId(owner));
411	        owner.setNamesakeCount(countNamesakes(owner));
412	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
413	        if (declaredMember) {
414	            owner.setPossibleDuplicate(false);
415	            owner.setPossibleDuplicateOf(null);
416	        } else {
417	            assignPossibleDuplicate(owner);
418	        }
419	    }
420	
421	    /**
422	     * Whether {@code owner} would join an existing household, i.e. some already-registered owner
423	     * resolves to the same {@link #householdId(Owner) householdId} (same last name and postcode).
424	     * Because the household is keyed on (last name, postcode), such a create is a household duplicate
425	     * and is rejected with {@code 409 CONFLICT} unless the request sets {@code sharesHousehold}, in
426	     * which case the owner is created as a declared household member.
427	     */
428	    private boolean hasExistingHousehold(Owner owner) {
429	        return !findHousemates(owner).isEmpty();
430	    }
431	
432	    /**
433	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
434	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
435	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
436	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
437	     * to the matching owner's id. Runs before save, against the existing owner population.
438	     */
439	    private void assignPossibleDuplicate(Owner owner) {
440	        Integer matchId = findPossibleDuplicateOf(owner);
441	        owner.setPossibleDuplicate(matchId != null);
442	        owner.setPossibleDuplicateOf(matchId);
443	    }
444	
445	    /**
446	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
447	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
448	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
449	     * never matches.
450	     */
451	    private Integer findPossibleDuplicateOf(Owner owner) {
452	        String postcode = owner.getPostcode();
453	        if (postcode == null) {
454	            return null;
455	        }
456	        String lastName = normalizeHouseholdField(owner.getLastName());
457	        String telephone = owner.getTelephone();
458	        return this.clinicService.findAllOwners().stream()
459	            .filter(existing -> existing.getId() != null
460	                && postcode.equals(existing.getPostcode())
461	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
462	                && !telephone.equals(existing.getTelephone()))
463	            .map(Owner::getId)
464	            .min(Integer::compareTo)
465	            .orElse(null);
466	    }
467	
468	    /**
469	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
470	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
471	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
472	     * owner's last name (e.g. 'NSW-1A2B3C4D'). There are no sequence numbers: the identity is a pure
473	     * function of the region and the (telephone, last name) pair.
474	     */
475	    private String generateCustomerCode(Owner owner) {
476	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
477	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
478	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
479	        return owner.getRegion() + "-" + hash8;
480	    }
481	
482	    /**
483	     * The number of existing owners registered in {@code city}, compared case-insensitively
484	     * with collapsed whitespace.
485	     */
486	    private int countOwnersInCity(String city) {
487	        String normalized = normalizeHouseholdField(city);
488	        return (int) this.clinicService.findAllOwners().stream()
489	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
490	            .count();
491	    }
492	
493	    /**
494	     * The effective registration date to store for a new owner: the date supplied on the request
495	     * when present, otherwise the current server date, in either case rolled forward to a business
496	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
497	     * This single point of resolution is what every registration-date-derived value (the stored
498	     * date, the membership number's year segment, the per-day create-limit) is computed from.
499	     */
500	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
501	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
502	        return toBusinessDay(date);
503	    }
504	
505	    /**
506	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
507	     * following Monday; a weekday is returned unchanged.
508	     */
509	    private static LocalDate toBusinessDay(LocalDate date) {
510	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
511	            date = date.plusDays(1);
512	        }
513	        return date;
514	    }
515	
516	    /**
517	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
518	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
519	     */
520	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
521	        String yy = String.format("%02d", registrationDate.getYear() % 100);
522	        return customerCode + "-M" + yy;
523	    }
524	
525	    /**
526	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
527	     * last name, compared case-insensitively.
528	     */
529	    private int countNamesakes(Owner owner) {
530	        String firstName = normalizeHouseholdField(owner.getFirstName());
531	        String lastName = normalizeHouseholdField(owner.getLastName());
532	        return (int) this.clinicService.findAllOwners().stream()
533	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
534	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
535	            .count();
536	    }
537	
538	    /**
539	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
540	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
541	     * unusually high daily signup volume.
542	     */
543	    private boolean isBulkSignupWarning() {
544	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
545	    }
546	
547	    /** The number of existing owners whose registration date is {@code date}. */
548	    private int countOwnersRegisteredOn(LocalDate date) {
549	        return (int) this.clinicService.findAllOwners().stream()
550	            .filter(existing -> date.equals(existing.getRegistrationDate()))
551	            .count();
552	    }
553	
554	    /**
555	     * The single derived key all duplicate detection flows through, formed from the owner's
556	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
557	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
558	     * id is derived, so the household segment is empty at that point. Because the telephone is part
559	     * of the key, two owners in the same household with different telephones resolve to different
560	     * keys and are both allowed.
561	     */
562	    private static String identityKey(Owner owner) {
563	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
564	        String email = owner.getEmail() == null ? "" : owner.getEmail();
565	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
566	        return telephone + "|" + email + "|" + household;
567	    }
568	
569	    /**
570	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
571	     * duplicate condition: the previously separate telephone, email and household checks are now all
572	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
573	     * trips it is rejected with {@code 409 CONFLICT}.
574	     */
575	    private boolean isDuplicate(Owner owner) {
576	        String key = owner.getIdentityKey();
577	        return this.clinicService.findAllOwners().stream()
578	            .map(Owner::getIdentityKey)
579	            .filter(existing -> existing != null)
580	            .anyMatch(key::equals);
581	    }
582	
583	    /** Common street-type abbreviations expanded during address normalization. */
584	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
585	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
586	
587	    /**
588	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
589	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
590	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
591	     * string when {@code address} is null or blank after normalization.
592	     */
593	    private static String normalizeAddress(String address) {
594	        if (address == null) {
595	            return "";
596	        }
597	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
598	        if (collapsed.isEmpty()) {
599	            return "";
600	        }
601	        StringBuilder sb = new StringBuilder(collapsed.length());
602	        for (String token : collapsed.split(" ")) {
603	            if (sb.length() > 0) {
604	                sb.append(' ');
605	            }
606	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
607	        }
608	        return sb.toString();
609	    }
610	
611	    /**
612	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
613	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
614	     */
615	    private static String normalizeHouseholdField(String value) {
616	        if (value == null) {
617	            return "";
618	        }
619	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
620	    }
621	
622	    /**
623	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
624	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
625	     * key rather than re-derived from the underlying fields here, so the household is described in one
626	     * place and every household-keyed value stays consistent with it.
627	     */
628	    private List<Owner> findHousemates(Owner owner) {
629	        String householdId = householdId(owner);
630	        return this.clinicService.findAllOwners().stream()
631	            .filter(existing -> householdId(existing).equals(householdId))
632	            .toList();
633	    }
634	
635	    /**
636	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
637	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
638	     */
639	    private int countHouseholdMembers(Owner owner) {
640	        return findHousemates(owner).size() + 1;
641	    }
642	
643	    /**
644	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
645	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
646	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
647	     * string standing in for a missing postcode), so housemates always resolve to the same value
648	     * regardless of registration order, and owners sharing a last name and postcode share it
649	     * automatically.
650	     */
651	    private static String householdId(Owner owner) {
652	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
653	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
654	        return sha256Hex(key).substring(0, 12);
655	    }
656	
657	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
658	    private static String sha256Hex(String input) {
659	        try {
660	            byte[] digest = MessageDigest.getInstance("SHA-256")
661	                .digest(input.getBytes(StandardCharsets.UTF_8));
662	            StringBuilder sb = new StringBuilder(digest.length * 2);
663	            for (byte b : digest) {
664	                sb.append(String.format("%02X", b));
665	            }
666	            return sb.toString();
667	        }
668	        catch (NoSuchAlgorithmException e) {
669	            throw new IllegalStateException("SHA-256 not available", e);
670	        }
671	    }
672	}
